import{_ as t,o as a,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"变色效应","description":"","frontmatter":{"title":"变色效应","phenomenon":"color-change"},"headers":[],"relativePath":"zh/classification/optical-phenomena/color-change.md","filePath":"zh/classification/optical-phenomena/color-change.md","lastUpdated":1790876393000}'),o={name:"zh/classification/optical-phenomena/color-change.md"};function n(d,e,i,c,h,s){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="变色效应" tabindex="-1">变色效应 <a class="header-anchor" href="#变色效应" aria-label="Permalink to &quot;变色效应&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>某些宝石在日光（含较多蓝绿光）与白炽灯（含较多红黄光）下呈现 明显不同颜色。最著名的是亚历山大石（变石），日光下绿色，白炽 灯下红色。其他含 Cr³⁺ / V³⁺ 的宝石（蓝宝石、镁铝榴石、尖晶石 变种）也可表现该效应。机制与变石的 Cr³⁺ 双重吸收带有关。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Cr³⁺ 离子具有两个主吸收带：一个在黄光区（约 580 nm），一个在 蓝光区（约 425 nm）。当日光（蓝绿富）照射时，黄色透射为主 → 视觉为绿色；当白炽灯（红黄富）照射时，黄光被吸收，蓝色透射 主导，与红色环境光共同呈现红/紫色效果。绿色与红色的对比越强， 变石效应评级越高。</p><h2 id="示例宝石" tabindex="-1">示例宝石 <a class="header-anchor" href="#示例宝石" aria-label="Permalink to &quot;示例宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>日光下</th><th>白炽灯下</th></tr></thead><tbody><tr><td>Alexandrite / 亚历山大石</td><td>green / teal</td><td>red / raspberry</td></tr><tr><td>Color-change Sapphire / 变色蓝宝</td><td>blue</td><td>purple</td></tr><tr><td>Color-change Garnet / 变色石榴石</td><td>blue-green</td><td>red-purple</td></tr><tr><td>Color-change Spinel / 变色尖晶石</td><td>blue</td><td>violet</td></tr><tr><td>Color-change Fluorite / 变色萤石</td><td>blue</td><td>purple</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA：现象宝石指南</a><span>光学现象的观察方式与宝石学语境</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA：现象弧面宝石的光学效应</a><span>弧面切割、光源、角度与光学表现</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">光学现象总览</a>。</em></p>',9)])])}const b=t(o,[["render",n]]);export{m as __pageData,b as default};
